static void permutacion(LinkedList<Integer>L1,
                         LinkedList<Integer>L2,
                         int r){

    if(L1.size()==r){
        System.out.println(L1);
        return;
    }

    for(int k=0;k<L2.size();k++){
        // SR: if(!L1.contains(L2.get(k)))
        // CR: sin filtro
        L1.add(L2.get(k));
        // llamada sin i
        L1.removeLast();
    }
}
